WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY units DESC NULLS FIRST, id) AS dedup_rank FROM store_sales) ranked WHERE dedup_rank = 1) SELECT product_id, DATE_TRUNC('QUARTER', sale_date) AS quarter_start, CASE WHEN revenue >= 3200 THEN 'HIGH' ELSE 'LOW' END AS revenue_tier, APPROX_PERCENTILE(units, 0.9) AS units_p90, ROUND(AVG(units), 2) AS avg_units, ROUND(AVG(revenue), 2) AS avg_revenue FROM deduped GROUP BY product_id, DATE_TRUNC('QUARTER', sale_date), CASE WHEN revenue >= 3200 THEN 'HIGH' ELSE 'LOW' END ORDER BY quarter_start DESC
